import{z as n,x as s,o as e,c as d,q as t,j as l,D as A,d as B,s as o,S as i,b as a}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"健康与保险收束","description":"","frontmatter":{"title":"健康与保险收束","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/hi-map.md","filePath":"econ/hi-map.md","lastUpdated":1791413859000}'),p={name:"econ/hi-map.md"};function m(D,E,h,c,C,F){const r=s("Mermaid");return e(),d("div",null,[E[2]||(E[2]=t('<h1 id="健康与保险收束" tabindex="-1">健康与保险收束 <a class="header-anchor" href="#健康与保险收束" aria-label="Permalink to &quot;健康与保险收束&quot;">​</a></h1><div class="epigraph"><p>健康经济学不是一门关于特殊商品的学问；它是把不确定性、信息不对称与第三方支付叠在普通商品上之后，问市场制度还剩下什么。</p><footer>—— 据 Arrow, AER 1963；Rothschild and Stiglitz, QJE 1976；Cutler and Zeckhauser 2000 整理</footer></div><p><a href="/econ/hi-drug-pricing">上一课</a>把固定成本、专利与第三方支付的交点写完。本课程到此收束：把四课的工具并成一张图，指出每种制度在「保险价值对激励损失」这把尺上的位置，并说清这门课没有覆盖什么。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>健康市场为什么值得整门课，而不是<a href="/econ/risk-aversion">风险厌恶</a>与<a href="/econ/moral-hazard">道德风险</a>两课的加总？因为三层结构叠加之后，产生了单独不存在的问题。第一层，风险厌恶要求保险——这部分是通用的。第二层，保险改变行为：用量与预防两个边际同时动，这是第一课的楔子。第三层，类型私有：谁最想要慷慨的保单，本身就是信息，这是第二课的机器。两层一起，保单条款不再是风险偏好的镜像，而同时是激励装置与筛选装置；再往产业与家庭两侧延伸，就有了药品的动态定价与健康存量的劳动供给。缺口从来不是「市场失灵」四个字，而是失灵在哪一层、制度补哪一维。</p><p><span class="marginnote">直觉类比：三层叠加像往同一杯水里同时加盐、加糖、加热——单看每样都还好，叠到一起析出的晶体（死亡螺旋、专利悬崖、工作锁定）在任何单独实验里都见不到。</span></p><p><span class="marginnote">把四课排成一张对照表：免赔额与共保率对道德风险；强制投保、社区评级与风险调整对风险选择；专利长度与 QALY 阈值对动态激励；可携带性与伤残保险对劳动配置。每种制度都只作用于各自的可观测维度。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>收束用同一把尺读四个对象。保险价值一侧：风险平滑、健康投资的补贴、创新的动态激励。激励损失一侧：用量楔子、预防塌陷、选择与死亡螺旋、垄断加价与可及性下降。每课的最优点都是内部解：共保率停在平滑与楔子的边际相等处，风险调整的分数停在可观测维度的边界上，专利长度停在动态激励与静态损失的边际相等处，价值定价的阈值本身就是这把尺的行政化。这门课的方法因此不是一张失灵清单，而是一个重复出现的权衡结构——把它认出来，比记住每课的结论更可迁移。</p>',9)),(e(),l(i,null,{default:A(()=>[o(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20RA%5B%22%E9%A3%8E%E9%99%A9%E5%8E%8C%E6%81%B6%EF%BC%9A%E8%A6%81%E4%BF%9D%E9%99%A9%22%5D%20--%3E%20MH%5B%22%E9%81%93%E5%BE%B7%E9%A3%8E%E9%99%A9%EF%BC%9A%E7%94%A8%E9%87%8F%E4%B8%8E%E9%A2%84%E9%98%B2%E4%B8%A4%E4%B8%AA%E6%A5%94%E5%AD%90%22%5D%0A%20%20TYPE%5B%22%E7%B1%BB%E5%9E%8B%E7%A7%81%E6%9C%89%EF%BC%9A%E9%A3%8E%E9%99%A9%E9%80%89%E6%8B%A9%22%5D%20--%3E%20MH%0A%20%20MH%20--%3E%20INST%5B%22%E5%88%B6%E5%BA%A6%EF%BC%9A%E5%85%B1%E4%BF%9D%E7%8E%87%E3%80%81%E9%A3%8E%E9%99%A9%E8%B0%83%E6%95%B4%E3%80%81%E5%BC%BA%E5%88%B6%E6%8A%95%E4%BF%9D%22%5D%0A%20%20HK%5B%22%E5%81%A5%E5%BA%B7%E5%AD%98%E9%87%8F%EF%BC%9A%E5%8A%B3%E5%8A%A8%E4%BE%9B%E7%BB%99%22%5D%20--%3E%20FRIC%5B%22%E4%BF%9D%E9%99%A9%E4%BD%9C%E4%B8%BA%E5%8A%B3%E5%8A%A8%E5%B8%82%E5%9C%BA%E7%9A%84%E6%91%A9%E6%93%A6%22%5D%0A%20%20RD%5B%22%E8%8D%AF%E5%93%81%E5%9B%BA%E5%AE%9A%E6%88%90%E6%9C%AC%22%5D%20--%3E%20PAT%5B%22%E4%B8%93%E5%88%A9%E4%B8%8E%E4%BB%B7%E5%80%BC%E5%AE%9A%E4%BB%B7%22%5D%0A%20%20INST%20--%3E%20MAP%5B%22%E6%94%B6%E6%9D%9F%EF%BC%9A%E4%BF%9D%E9%99%A9%E4%BB%B7%E5%80%BC%E5%AF%B9%E6%BF%80%E5%8A%B1%E6%8D%9F%E5%A4%B1%22%5D%0A%20%20FRIC%20--%3E%20MAP%0A%20%20PAT%20--%3E%20MAP%0A"})]),fallback:A(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[B("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,[B("叠加是本课程真正的机制题。选择与道德风险互相放大：慷慨计划吸引高风险者与高使用者，费率涨得比任一单独效应快，这是第二课。保险补贴健康投资，健康存量又决定劳动收入，保单由此进了劳动市场，这是第三课。第三方支付压低弹性，专利加价更硬，药价反过来推高保单——闭环在这里合拢：保险、选择与定价不是三个市场，是一个市场的三个面，这是第四课。"),a("a",{href:"/econ/welfare-theorems"},"福利两定理"),B("的前提在每一层都被打破，所以制度不是对市场的干预，而是对失效前提的替换：强制投保替换参与约束，风险调整替换缺失的或有市场，专利替换知识市场的收费装置，公共保险替换不可保的大风险。")],-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"术语翻译：死亡螺旋=选择自我强化的循环——慷慨保单吸引高风险者，保费被推高，健康者退出，池子风险更高，保费再涨。转起来没有稳定点，除非有强制投保或风险调整按住它。")],-1)),(e(),l(i,null,{default:A(()=>[o(r,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20P1%5B%22%E5%8F%82%E4%B8%8E%E7%BA%A6%E6%9D%9F%E5%A4%B1%E6%95%88%3A%20%E7%97%85%E4%BA%BA%E6%9C%80%E6%83%B3%E6%8A%95%E4%BF%9D%22%5D%20--%3E%20S1%5B%22%E5%BC%BA%E5%88%B6%E6%8A%95%E4%BF%9D%E4%B8%8E%E7%A4%BE%E5%8C%BA%E8%AF%84%E7%BA%A7%22%5D%0A%20%20P2%5B%22%E7%B1%BB%E5%9E%8B%E4%B8%8D%E5%8F%AF%E5%AE%9A%E4%BB%B7%3A%20%E6%88%96%E6%9C%89%E5%B8%82%E5%9C%BA%E7%BC%BA%E5%A4%B1%22%5D%20--%3E%20S2%5B%22%E9%A3%8E%E9%99%A9%E8%B0%83%E6%95%B4%E4%BF%9D%E8%B4%B9%22%5D%0A%20%20P3%5B%22%E7%9F%A5%E8%AF%86%E6%94%B6%E8%B4%B9%E9%9A%BE%3A%20%E9%9D%9E%E7%AB%9E%E4%BA%89%E6%80%A7%22%5D%20--%3E%20S3%5B%22%E4%B8%93%E5%88%A9%E5%8A%A0%E4%B8%8A%20QALY%20%E9%98%88%E5%80%BC%22%5D%0A%20%20P4%5B%22%E5%A4%A7%E9%A3%8E%E9%99%A9%E5%B8%82%E5%9C%BA%E4%B8%8D%E5%8F%AF%E4%BF%9D%22%5D%20--%3E%20S4%5B%22%E5%85%AC%E5%85%B1%E4%BF%9D%E9%99%A9%E5%85%9C%E5%BA%95%22%5D%0A"})]),fallback:A(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>没写的不等于不存在：医院竞争与质量规制、医生支付方式（按项目付费把道德风险搬到供给侧，按人头付费是同一楔子贴在医生身上）、卫生支出占总收入比重的长期增长、公共卫生的外部性——传染病预防是<a href="/econ/public-goods">公共物品</a>课的对象，本课程只在收束处点名。年金与长期护理属于跨期与家庭金融。这些留白有共同点：都要把本课程的权衡结构搬进新的商品空间，而不是新的经济学。</p><p><span class="marginnote">常见误区：「市场失灵=让政府接管就好」。失灵在哪一层决定工具是什么：楔子层用自付与免赔额，选择层用强制与风险调整，产业层用专利与阈值。拿错层的工具，往往把另一层的失效放大。</span></p><p>本课程到此收束。带走三件事：楔子、筛选、与「保险价值对激励损失」的内部解。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>健康市场的特殊性是三层叠加：风险厌恶要保险，保险改行为，投保决策泄露类型。</li><li>每种制度对应一层失灵的一个可观测维度；选择只会换维度，不会消失。</li><li>药品定价与健康劳动供给是同一权衡在产业侧与家庭侧的延伸。</li><li>闭环：保单、选择与药价互相定价，是一个市场的三个面。</li><li>出处：Arrow, <em>AER</em> 1963；Pauly, <em>AER</em> 1968；Rothschild–Stiglitz, <em>QJE</em> 1976；Cutler–Zeckhauser 2000；Grossman, <em>JPE</em> 1972。</li></ul>',6))])}const P=n(p,[["render",m]]);export{f as __pageData,P as default};
